/**
 * Client-side image preview helper using FileReader / Data URL.
 * Supports both single file and multiple files upload.
 * Later replaceable with multipart/form-data upload to Cloudinary / backend API.
 */
export const uploadService = {
  /**
   * Converts a browser File object into a base64 Data URL
   * so it persists across page refreshes in localStorage during frontend testing.
   */
  readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
      if (!file) {
        reject(new Error('No file provided'))
        return
      }
      if (!file.type.startsWith('image/')) {
        reject(new Error('Please select a valid image file (JPG, PNG, WEBP).'))
        return
      }

      const reader = new FileReader()
      reader.onload = (event) => {
        const img = new Image()
        img.onload = () => {
          const maxDim = 900
          let { width, height } = img
          if (width > maxDim || height > maxDim) {
            if (width > height) {
              height = Math.round((height * maxDim) / width)
              width = maxDim
            } else {
              width = Math.round((width * maxDim) / height)
              height = maxDim
            }
          }
          const canvas = document.createElement('canvas')
          canvas.width = width
          canvas.height = height
          const ctx = canvas.getContext('2d')
          ctx.drawImage(img, 0, 0, width, height)
          try {
            const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.82)
            resolve({
              id: `photo-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
              url: compressedDataUrl,
              name: file.name,
              size: file.size
            })
          } catch {
            resolve({
              id: `photo-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
              url: event.target.result,
              name: file.name,
              size: file.size
            })
          }
        }
        img.onerror = () => {
          resolve({
            id: `photo-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            url: event.target.result,
            name: file.name,
            size: file.size
          })
        }
        img.src = event.target.result
      }
      reader.onerror = () => reject(new Error('Failed to read image file.'))
      reader.readAsDataURL(file)
    })
  },

  /**
   * Reads multiple File objects in parallel and returns an array of photo objects.
   */
  async readMultipleFilesAsDataUrls(fileList) {
    const files = Array.from(fileList || []).filter(f => f && f.type.startsWith('image/'))
    if (!files.length) {
      throw new Error('Please select one or more valid image files (JPG, PNG, WEBP).')
    }
    return Promise.all(files.map(file => this.readFileAsDataUrl(file)))
  }
}
